function rupees(n) {
  return '₹' + Number(n || 0).toLocaleString('en-IN')
}
function inStage(rows, stage) {
  return (rows || []).filter(s => s.stage === stage)
}
function total(rows, stages) {
  return (rows || []).filter(s => stages.includes(s.stage)).reduce((t, s) => t + (s.amount || 0), 0)
}
function tierTheme(tier) {
  return { Platinum: 'violet', Gold: 'amber', Silver: 'gray', Community: 'green' }[tier] || 'gray'
}

